            'vlan batch 10 20 99\ninterface GigabitEthernet0/0/1\n port link-type access\n port default vlan 10\ninterface GigabitEthernet0/0/24\n port link-type trunk\n port trunk allow-pass vlan 10 20 99\ninterface Vlanif10\n ip address 10.64.10.1 255.255.255.0',
